		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/*
 * Optimized kernel implementation in Exo.
 *
 * We start from a clear mathematical specification of GEMM and then
 * apply Exo scheduling primitives to:
 *  - hoist scalar parameters alpha/beta into locals (fewer memory loads),
 *  - tile the reduction dimension k and the output column dimension j
 *    to improve cache locality and enable better compiler auto-vectorization,
 *  - parallelize the outer i loops (both the scaling phase and the main GEMM)
 *    using OpenMP.
 *
 * All transformations are semantics-preserving: the final kernel computes
 *   C = beta * C + alpha * A * B
 * exactly as in the original PolyBench GEMM.
 */
/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# ---------------------------------------------------------------------------
# Tuning parameters (tile sizes).
# These can be adjusted to better match a particular machine's cache sizes.
# ---------------------------------------------------------------------------

TI = 32  # currently unused, but left for potential future i-tiling
TJ = 64  # tile size along output columns j
TK = 64  # tile size along reduction dimension k


@proc
def kernel_gemm_base(
    ni: size,
    nj: size,
    nk: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
):
    # -----------------------------------------------------------------------
    # Hoist scalar parameters into local scalars.
    # In the generated C this will read *alpha and *beta once, then use
    # the local copies alpha_val/beta_val in the hot loops, reducing
    # pointer dereferences and enabling better optimization.
    # -----------------------------------------------------------------------
    alpha_val: DATA_TYPE
    beta_val: DATA_TYPE

    alpha_val = alpha
    beta_val = beta

    # -----------------------------------------------------------------------
    # Phase 1: scale C by beta.
    #   C[i, j] = beta * C[i, j]
    # This loop is independent of A and B and of the later GEMM phase.
    # -----------------------------------------------------------------------
    for i in seq(0, ni):
        for j in seq(0, nj):
            C[i, j] = beta_val * C[i, j]

    # -----------------------------------------------------------------------
    # Phase 2: main GEMM update
    #   C[i, j] += alpha * A[i, k] * B[k, j]
    #
    # Loop ordering:
    #   i (rows of C / A)
    #   k (reduction dimension)
    #   j (columns of C / B)
    #
    # For each fixed (i, k), we walk j as the innermost loop, which accesses
    # B[k, j] and C[i, j] with unit stride in memory (row-major layout),
    # while A[i, k] is reused across the full inner j loop.
    #
    # We also introduce a_ik = alpha_val * A[i, k], computed once per (i, k)
    # and reused across the j loop. This saves one multiplication per j
    # and makes the inner loop lighter for auto-vectorization.
    # -----------------------------------------------------------------------
    for i in seq(0, ni):
        for k in seq(0, nk):
            a_ik: DATA_TYPE
            a_ik = alpha_val * A[i, k]
            for j in seq(0, nj):
                C[i, j] += a_ik * B[k, j]


# ---------------------------------------------------------------------------
# Scheduling: tiling and parallelization.
# ---------------------------------------------------------------------------

# Tile the reduction dimension k in the main GEMM nest (the only k loop).
# This improves temporal locality for A and B and allows the compiler
# to work on smaller k-blocks at a time.
kernel1 = divide_loop(kernel_gemm_base, "k", TK, ("ko", "ki"), tail="guard")

# Tile the j loop of the main GEMM phase.
# There are two j loops in the procedure: the first in the scaling phase,
# the second in the GEMM phase. "j #1" selects the second one.
# Tiling j improves cache locality for C and B and exposes a small,
# fixed-size inner loop (over ji) that the backend compiler can
# vectorize efficiently.
kernel2 = divide_loop(kernel1, "j #1", TJ, ("jo", "ji"), tail="guard")

# Parallelize the outer i loop of the scaling phase.
# This loop is embarrassingly parallel: each (i, :) row of C is independent.
kernel3 = parallelize_loop(kernel2, "i #0")

# Parallelize the outer i loop of the main GEMM phase.
# Again, rows of C are independent; each thread works on a disjoint
# subset of rows, so there are no data races.
kernel4 = parallelize_loop(kernel3, "i #1")

# Clean up loop bounds and guards introduced by tiling, and generally
# simplify the IR before code generation.
kernel_gemm_sched = simplify(kernel4)

# Expose the scheduled kernel under the external name expected by the
# C driver and the generated header.
kernel_gemm = rename(kernel_gemm_sched, "kernel_gemm")

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_gemm (/*ctxt=*/NULL, ni, nj, nk,
	       (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	       (DATA_TYPE*)POLYBENCH_ARRAY(C),
	       (DATA_TYPE*)POLYBENCH_ARRAY(A),
	       (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
